private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get() & 0xFF;
        if (b <= 0x7F) {
            sb.append((char) b);
        } else if (b <= 0xBF) {
            // Continuation byte, should not be the first
            return i - 1; // Malformed sequence
        } else if (b <= 0xDF) {
            // 2-byte sequence
            int b2 = bb.get() & 0xFF;
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
            i += 1;
        } else if (b <= 0xEF) {
            // 3-byte sequence
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
            i += 2;
        } else if (b <= 0xF7) {
            // 4-byte sequence
            int b2 = bb.get() & 0xFF;
            int b3 = bb.get() & 0xFF;
            int b4 = bb.get() & 0xFF;
            sb.appendCodePoint((((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F)));
            i += 3;
        } else {
            // Invalid start byte
            return i - 1; // Malformed sequence
        }
        i++;
    }
    return i;
}

