public int readTag() throws IOException {
    int b = this.read();
    if (b == -1) {
        return 0; // EOF
    }
    int fieldNumber = b & 0x7f;
    int wireType = b >> 7;
    while ((b & 0x80) != 0) {
        b = this.read();
        if (b == -1) {
            throw new IOException("Coded input contains interleaved messages.");
        }
        fieldNumber = (fieldNumber << 7) | (b & 0x7f);
    }
    return wireType << 3 | fieldNumber;
}

